let pay = flow.get("slides").length;
node.status({text:pay});
flow.set("numSlides", pay);
return msg;

let numSlides = flow.get("numSlides");
let slideIndex = flow.get("slideIndex") || 0;
slideIndex++;
if (slideIndex > numSlides - 1) slideIndex = 0;
flow.set("slideIndex", slideIndex);
msg.slideIndex = slideIndex;
return msg;

msg.payload = flow.get("slides")[msg.slideIndex];
node.status({"text" : msg.payload});
msg.filename = "/home/STUDENT_17/iug/" + msg.payload;
return msg;

let numSlides = flow.get("numSlides");
let slideIndex = flow.get("slideIndex") || 0;
slideIndex--;
if (slideIndex < 0) slideIndex = numSlides - 1;
flow.set("slideIndex", slideIndex);
msg.slideIndex = slideIndex;
return msg;

let read = global.get("gate.slide");
let status = read ? "Opened" : "Closed";
let color  = read ? "green" : "red";
node.status({fill:color,shape:"ring",text:status});
return msg;

let currentValues = flow.get('control');
let currentTime = new Date().getTime();

// Retrieve the previous value and timestamp from the context
let previousData = context.get('previousValues') || {};
let previousValues = previousData.value;
let previousTimestamp = previousData.timestamp || 0;

// Check if the current value is different from the previous value
if (currentValues !== previousValues || 
    ((currentValues === 'arrow-right' || currentValues === 'arrow-left') && currentTime !== previousTimestamp)) {

    // Update the context with the new value and timestamp
    context.set('previousValues', { value: currentValues, timestamp: currentTime });

    // Send a message to trigger the next node
    msg.payload = currentValues;
    return msg;
} else {
    // If the value hasn't changed and doesn't meet the specific conditions, do nothing
    return null;
}
